package glitch

import data.glitch_lib

sensitive_fields := {"password", "pass", "pwd", "secret", "token", "key", "apikey", "accesskey", "secretkey", "privatekey", "credential", "auth"}

contains_sensitive_keyword(str) {
    field := sensitive_fields[_]
    regex.match(sprintf("(?i).*%s.*", [field]), str)
}

contains_hardcoded_credential(expr) {
    expr.ir_type == "Hash"
    pair := expr.value[_]
    key := pair.key
    value := pair.value
    key.ir_type == "String"
    key.value in sensitive_fields
    value.ir_type == "String"
} else {
    expr.ir_type == "Hash"
    contains_hardcoded_credential(expr.value[_].value)
} else {
    expr.ir_type == "Array"
    contains_hardcoded_credential(expr.value[_])
} else {
    false
}

check_variable(var) {
    var.ir_type == "Variable"
    contains_sensitive_keyword(var.name)
    var.value.ir_type == "String"
} else {
    var.ir_type == "Variable"
    contains_hardcoded_credential(var.value)
}

check_attribute(attr) {
    attr.ir_type == "Attribute"
    contains_sensitive_keyword(attr.name)
    attr.value.ir_type == "String"
} else {
    attr.ir_type == "Attribute"
    contains_hardcoded_credential(attr.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    var := variables[_]
    check_variable(var)
    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid embedding sensitive credentials in code. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attributes := glitch_lib.all_attributes(parent)
    attr := attributes[_]
    check_attribute(attr)
    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Avoid embedding sensitive credentials in code. (CWE-798)"
